using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Reflection;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Windows.Media;
public static class V124Tests {
 static List<string> log=new List<string>();
 static T Field<T>(object o,string n){return (T)o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).GetValue(o);}
 static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).Invoke(o,a);}
 static void Check(bool ok,string text){if(!ok)throw new Exception(text);log.Add("PASS "+text);}
 static IEnumerable<DependencyObject> Walk(DependencyObject o){yield return o;for(int i=0;i<VisualTreeHelper.GetChildrenCount(o);i++)foreach(var child in Walk(VisualTreeHelper.GetChild(o,i)))yield return child;}
 static void Click(Window w,string text){var button=Walk(w).OfType<Button>().Single(b=>Equals(b.Content,text));button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}
 static void Drag(PaneDivider divider,double delta){divider.UpdateLayout();divider.RaiseEvent(new DragStartedEventArgs(0,0){RoutedEvent=Thumb.DragStartedEvent});divider.RaiseEvent(new DragDeltaEventArgs(delta,0){RoutedEvent=Thumb.DragDeltaEvent});divider.RaiseEvent(new DragCompletedEventArgs(delta,0,false){RoutedEvent=Thumb.DragCompletedEvent});}
 static async Task Ready(TerminalView view){for(int i=0;i<100;i++){if(view.DiagnosticReady)return;await Task.Delay(100);}throw new Exception("Terminal ready "+view.State);}
 public static async void Run(Application app,string folder){Directory.CreateDirectory(folder);string oldStorage=Storage.PathName,oldLayout=PaneLayouts.PathName;MonitorWindow w=null;SettingsWindow editor=null;try{
 Storage.PathName=Path.Combine(folder,"settings.xml");PaneLayouts.PathName=Path.Combine(folder,"layout-"+Guid.NewGuid().ToString("N")+".xml");PaneLayouts.Reload();w=new MonitorWindow(true){ShowActivated=false,ShowInTaskbar=false,Left=-18000,Top=-18000,WindowStartupLocation=WindowStartupLocation.Manual,Width=1440,Height=900};w.Show();w.ChooseServer(Storage.LocalServer());w.SetMetrics(Program.Fixture("eight"),false);w.SwitchView("文件");await Task.Delay(250);w.UpdateLayout();
 var files=w.FileView;var dual=Field<Grid>(files,"dualGrid");var fileDivider=dual.Children.OfType<PaneDivider>().Single();Check(fileDivider.Visibility==Visibility.Collapsed&&dual.ColumnDefinitions[0].ActualWidth<1,"local file mode has no empty left pane");Field<FileWorkspace>(files,"localPane").Visibility=Visibility.Visible;fileDivider.Visibility=Visibility.Visible;dual.ColumnDefinitions[1].Width=new GridLength(16);fileDivider.Restore(true);w.UpdateLayout();double before=dual.ColumnDefinitions[0].ActualWidth;Drag(fileDivider,80);await Task.Delay(80);w.UpdateLayout();double after=dual.ColumnDefinitions[0].ActualWidth;log.Add("FILE_GEOMETRY width="+dual.ActualWidth+" handle="+fileDivider.ActualWidth+" before="+before+" after="+after+" left="+dual.ColumnDefinitions[0].Width+" right="+dual.ColumnDefinitions[2].Width);Check(after>before+50,"file divider responds to real drag events");double ratio=PaneLayouts.Get("files.columns",-1);Check(ratio>.45&&ratio<.9,"file ratio persisted");PaneLayouts.Reload();Check(Math.Abs(PaneLayouts.Get("files.columns",0)-ratio)<.00001,"file ratio survives disk reload");fileDivider.Restore(true);w.UpdateLayout();Check(Math.Abs(dual.ColumnDefinitions[0].Width.Value-1/2.25)<.00001,"double-click reset restores file ratio");
 Drag(fileDivider,60);await Task.Delay(80);w.RenderImage(Path.Combine(folder,"files-resized.png"),1440,900,120);w.Root.ClearValue(FrameworkElement.WidthProperty);w.Root.ClearValue(FrameworkElement.HeightProperty);
 var table=Field<DataGrid>(files,"files");w.UpdateLayout();var header=Walk(table).OfType<System.Windows.Controls.Primitives.DataGridColumnHeader>().First(h=>h.Column==table.Columns[0]);var grip=Walk(header).OfType<Thumb>().First(t=>t.Name=="PART_RightHeaderGripper");double originalColumn=table.Columns[0].ActualWidth;grip.RaiseEvent(new DragStartedEventArgs(0,0){RoutedEvent=Thumb.DragStartedEvent});grip.RaiseEvent(new DragDeltaEventArgs(50,0){RoutedEvent=Thumb.DragDeltaEvent});w.UpdateLayout();grip.RaiseEvent(new DragCompletedEventArgs(50,0,false){RoutedEvent=Thumb.DragCompletedEvent});double newColumn=table.Columns[0].ActualWidth;Check(newColumn>originalColumn+30,"file table column responds to header drag");files.ReflowColumns();w.UpdateLayout();Check(Math.Abs(table.Columns[0].ActualWidth-newColumn)<1,"table reflow retains manually resized columns");Check(Math.Abs(PaneLayouts.Get("files.table.0",0)-newColumn)<1,"table column width persisted");
 var rail=Field<PaneEdgeHandle>(w,"railResizer");double railBefore=w.Root.ColumnDefinitions[0].ActualWidth;rail.ResizeBy(32);w.UpdateLayout();rail.RaiseEvent(new DragCompletedEventArgs(32,0,false){RoutedEvent=Thumb.DragCompletedEvent});Check(w.Root.ColumnDefinitions[0].ActualWidth>railBefore+20,"workspace sidebar resizes");Check(PaneLayouts.Get("workspace.sidebar",0)>250,"sidebar width persisted");
 Call(w,"ToggleTransfers");await Task.Delay(50);var drawer=Field<TransferDrawer>(w,"transferDrawer");double drawerBefore=drawer.Width;var edge=Walk(drawer).OfType<PaneEdgeHandle>().Single();edge.ResizeBy(-50);w.UpdateLayout();edge.RaiseEvent(new DragCompletedEventArgs(-50,0,false){RoutedEvent=Thumb.DragCompletedEvent});Check(drawer.Width>drawerBefore+40,"transfer drawer resizes from left edge");Check(Math.Abs(new TransferDrawer().Width-drawer.Width)<.1,"transfer drawer width restored");drawer.Visibility=Visibility.Collapsed;
 w.SwitchView("终端");await Task.Delay(100);var terminal=w.TerminalView;await Ready(terminal.ActiveView);Call(terminal,"ToggleSplit");await Task.Delay(100);var sessions=Field<List<TerminalView>>(terminal,"sessions");await Ready(sessions[1]);var content=Field<Grid>(terminal,"content");var split=content.Children.OfType<PaneDivider>().Single();before=content.ColumnDefinitions[0].ActualWidth;Drag(split,40);await Task.Delay(100);w.UpdateLayout();Check(content.ColumnDefinitions[0].ActualWidth>before+20,"terminal split responds to drag");double terminalRatio=PaneLayouts.Get("terminal.split",-1);Check(terminalRatio>.5,"terminal ratio saved");Call(terminal,"Select",terminal.ActiveView);w.UpdateLayout();Check(Math.Abs(content.ColumnDefinitions[0].Width.Value-terminalRatio)<.00001,"tab selection preserves split ratio");
 var body=Field<Grid>(terminal,"body");var inspector=Field<PaneDivider>(terminal,"inspectorDivider");Check(inspector.Visibility==Visibility.Visible,"terminal inspector divider available");before=body.ColumnDefinitions[2].ActualWidth;Drag(inspector,-40);await Task.Delay(80);w.UpdateLayout();Check(body.ColumnDefinitions[2].ActualWidth>before+20,"terminal inspector resizes");double inspectorWidth=PaneLayouts.Get("terminal.inspector",0);Call(terminal,"SetInspectorVisibility");w.UpdateLayout();Check(Math.Abs(body.ColumnDefinitions[2].Width.Value-inspectorWidth)<.1,"inspector width survives refresh");
 int applied=0;Settings snapshot=null;editor=new SettingsWindow(w.CompactOptions.Copy(),true){Owner=w};editor.ApplyRequested+=(options,startup)=>{applied++;snapshot=options;Storage.Save(options);w.ApplyOptions(options.Copy());};Exception modalError=null;var dialog=editor;editor.Loaded+=(s,e)=>editor.Dispatcher.BeginInvoke((Action)(()=>{try{
 var frequency=Field<ComboBox>(dialog,"frequency");frequency.SelectedItem=null;Click(dialog,"应用");Check(applied==0&&dialog.IsVisible,"invalid settings do not apply or close");frequency.SelectedItem="10";Field<ComboBox>(dialog,"terminalFont").SelectedItem="Consolas";Field<ComboBox>(dialog,"terminalSize").SelectedItem="20";Field<ComboBox>(dialog,"themePicker").SelectedIndex=3;Click(dialog,"应用");Check(applied==1&&dialog.IsVisible&&dialog.DialogResult==null,"Apply persists settings and keeps dialog open");Check(w.CompactOptions.Interval==10&&w.CompactOptions.Terminal.FontSize==20,"Apply updates live monitor preferences");Check(Storage.Load().Interval==10&&Storage.Load().Terminal.FontSize==20,"Apply saves preferences on disk");Check(terminal.ActiveView!=null&&sessions.Count==2,"Apply retains existing terminal sessions");var deviceDivider=Walk(dialog.Root).OfType<PaneDivider>().Single();var deviceGrid=(Grid)deviceDivider.Parent;double old=deviceGrid.ColumnDefinitions[0].ActualWidth;Drag(deviceDivider,25);dialog.UpdateLayout();Check(deviceGrid.ColumnDefinitions[0].ActualWidth>old+10,"settings device list resizes");dialog.RenderImage(Path.Combine(folder,"settings-apply.png"),860,760,120);frequency.SelectedItem="30";Field<ComboBox>(dialog,"terminalSize").SelectedItem="12";dialog.Result.Servers[0].Name="未应用修改";Check(w.CompactOptions.Servers[0].Name!="未应用修改"&&snapshot.Servers[0].Name!="未应用修改","draft is isolated after Apply");Click(dialog,"取消");}catch(Exception ex){modalError=ex;dialog.Close();}}));
 bool? result=editor.ShowDialog();editor=null;if(modalError!=null)throw modalError;Check(result==false&&w.CompactOptions.Interval==10&&Storage.Load().Interval==10,"Cancel retains last applied settings");Check(w.CompactOptions.Terminal.FontSize==20,"Cancel drops subsequent font draft");
 editor=new SettingsWindow(w.CompactOptions.Copy(),true){Owner=w};dialog=editor;dialog.ApplyRequested+=(options,startup)=>{applied++;Storage.Save(options);w.ApplyOptions(options.Copy());};modalError=null;dialog.Loaded+=(s,e)=>dialog.Dispatcher.BeginInvoke((Action)(()=>{try{Field<ComboBox>(dialog,"frequency").SelectedItem="5";Click(dialog,"确定");}catch(Exception ex){modalError=ex;dialog.Close();}}));result=dialog.ShowDialog();editor=null;if(modalError!=null)throw modalError;Check(result==true&&w.CompactOptions.Interval==5,"Confirm applies and closes dialog");
 var tabs=Field<StackPanel>(terminal,"tabs");foreach(var view in sessions.ToArray()){var row=tabs.Children.OfType<Grid>().Single(r=>ReferenceEquals(r.Tag,view));Call(terminal,"Close",view,row);}w.UpdateLayout();Check(!content.Children.OfType<PaneDivider>().Any(),"last terminal close removes split handle");Check(inspector.Visibility==Visibility.Collapsed&&body.ColumnDefinitions[2].ActualWidth<1,"empty terminal collapses inspector");
 w.Exit();w=null;File.WriteAllLines(Path.Combine(folder,"v124-results.txt"),log);app.Shutdown(0);
 }catch(Exception ex){File.WriteAllLines(Path.Combine(folder,"v124-results.txt"),log);File.WriteAllText(Path.Combine(folder,"v124-error.txt"),ex.ToString());if(editor!=null)editor.Close();if(w!=null)w.Exit();app.Shutdown(1);}finally{Storage.PathName=oldStorage;PaneLayouts.PathName=oldLayout;PaneLayouts.Reload();}}
}

